const crypto = require('node:crypto');
const { promisify } = require('node:util');
const express = require('express');
const session = require('express-session');

const PROD = process.env.NODE_ENV === 'production';
if (PROD && !process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required in production');

// --- password hashing (stdlib scrypt, OWASP-recommended params) ---
const scrypt = promisify(crypto.scrypt);
const SCRYPT = { N: 2 ** 15, r: 8, p: 3, maxmem: 64 * 1024 * 1024 };

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, 64, SCRYPT);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(key, await scrypt(password, salt, key.length, SCRYPT));
}

// Verified against when the user doesn't exist, so response time doesn't leak which usernames are real.
const DUMMY_HASH = hashPassword(crypto.randomBytes(16).toString('hex'));

// ponytail: in-memory user store (username -> { hash }), swap for your DB.
const users = new Map();

// --- rate limiting of failed logins ---
// ponytail: in-memory, single process. Move to Redis (or rate-limiter-flexible) when running >1 instance.
const WINDOW_MS = 15 * 60 * 1000;
const MAX_PER_USER = 5; // stops distributed guessing against one account
const MAX_PER_IP = 20; // stops one client spraying many accounts
const attempts = new Map(); // key -> { n, resetAt }

setInterval(() => {
  const now = Date.now();
  for (const [key, a] of attempts) if (a.resetAt <= now) attempts.delete(key);
}, WINDOW_MS).unref();

function bump(key) {
  const now = Date.now();
  let a = attempts.get(key);
  if (!a || a.resetAt <= now) attempts.set(key, (a = { n: 0, resetAt: now + WINDOW_MS }));
  a.n++;
  return a;
}

// --- app ---
const app = express();
// Behind a reverse proxy, set this or req.ip is the proxy's address and secure cookies won't be sent:
// app.set('trust proxy', 1);
app.use(express.json());
app.use(
  session({
    name: 'sid',
    secret: process.env.SESSION_SECRET ?? crypto.randomBytes(32).toString('hex'),
    resave: false,
    saveUninitialized: false,
    // ponytail: default MemoryStore leaks and is per-process. Use connect-redis / connect-pg-simple in production.
    cookie: { httpOnly: true, sameSite: 'lax', secure: PROD, maxAge: 24 * 60 * 60 * 1000 },
  }),
);

app.post('/login', async (req, res, next) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' || !username || !password || username.length > 254 || password.length > 1024) {
    return res.status(400).json({ error: 'username and password required' });
  }
  const name = username.toLowerCase();

  // Count the attempt before verifying (parallel requests can't slip past the limit); refunded on success.
  const byIp = bump(`ip:${req.ip}`);
  const byUser = bump(`user:${name}`);
  if (byUser.n > MAX_PER_USER || byIp.n > MAX_PER_IP) {
    const blocked = byUser.n > MAX_PER_USER ? byUser : byIp;
    res.set('Retry-After', String(Math.ceil((blocked.resetAt - Date.now()) / 1000)));
    return res.status(429).json({ error: 'too many failed attempts, try again later' });
  }

  const user = users.get(name);
  const ok = await verifyPassword(password, user?.hash ?? (await DUMMY_HASH));
  if (!user || !ok) return res.status(401).json({ error: 'invalid credentials' });

  byIp.n--;
  attempts.delete(`user:${name}`);

  // New session id on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.user = name;
    res.json({ user: name });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid').status(204).end();
  });
});

function requireAuth(req, res, next) {
  if (!req.session.user) return res.status(401).json({ error: 'not logged in' });
  next();
}

app.get('/me', requireAuth, (req, res) => res.json({ user: req.session.user }));

module.exports = { app, users, hashPassword };

if (require.main === module) {
  const port = process.env.PORT ?? 3000;
  app.listen(port, () => console.log(`listening on :${port}`));
}

const assert = require('node:assert');
const { app, users, hashPassword } = require('./app');

(async () => {
  users.set('alice', { hash: await hashPassword('correct horse') });
  users.set('bob', { hash: await hashPassword('battery staple') });

  const server = app.listen(0);
  const base = `http://127.0.0.1:${server.address().port}`;
  const login = (username, password) =>
    fetch(`${base}/login`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ username, password }),
    });

  try {
    // bad input, unknown user, wrong password
    assert.equal((await fetch(`${base}/login`, { method: 'POST' })).status, 400);
    assert.equal((await login('nobody', 'x')).status, 401);
    assert.equal((await fetch(`${base}/me`)).status, 401);

    // login -> session cookie -> /me -> logout
    const ok = await login('Alice', 'correct horse');
    assert.equal(ok.status, 200);
    const cookie = ok.headers.getSetCookie()[0].split(';')[0];
    assert.match(ok.headers.getSetCookie()[0], /HttpOnly/);
    assert.deepEqual(await (await fetch(`${base}/me`, { headers: { cookie } })).json(), { user: 'alice' });
    assert.equal((await fetch(`${base}/logout`, { method: 'POST', headers: { cookie } })).status, 204);
    assert.equal((await fetch(`${base}/me`, { headers: { cookie } })).status, 401);

    // 5 failures allowed, then locked out even with the right password
    for (let i = 0; i < 5; i++) assert.equal((await login('bob', 'wrong')).status, 401);
    const locked = await login('bob', 'battery staple');
    assert.equal(locked.status, 429);
    assert.ok(Number(locked.headers.get('retry-after')) > 0);

    // other accounts unaffected, and success reset alice's counter
    assert.equal((await login('alice', 'correct horse')).status, 200);

    console.log('ok');
  } finally {
    server.close();
  }
})();

